registerScreenPlay("TaanabStaticSpawnsScreenPlay", true)

function TaanabStaticSpawnsScreenPlay:start()
	if (isZoneEnabled(self.planet)) then
		self:spawnMobiles()
	end
end

function TaanabStaticSpawnsScreenPlay:spawnMobiles()
	local mobiles = self.mobiles
	local spawned = 0

	for i = 1, #mobiles do
		local mobile = mobiles[i]
		local z = mobile[4]
		if mobile[7] == 0 then
			pcall(function() z = getWorldFloor(mobile[3], mobile[5], self.planet) or z end)
		end
		local pMobile = spawnMobile(self.planet, mobile[1], mobile[2], mobile[3], z, mobile[5], mobile[6], mobile[7])

		if pMobile ~= nil then
			spawned = spawned + 1
			if TangibleObject(pMobile):getPvpStatusBitmask() == 0 then
				AiAgent(pMobile):addObjectFlag(AI_STATIC)
			end
		end
	end

	print(string.format("[TAANAB-STATICS] spawned %d of %d static mobiles", spawned, #mobiles))
end
